using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static ReportingConfiguration _reportingConfig = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();

        _reportingConfig = new ReportingConfiguration(
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-results"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new GroundednessEvaluator(),
            ]);
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        await _app.DisposeAsync();
        await _appHost.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_responds_coherently()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_responds_coherently));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenario.EvaluateAsync(messages);

        var result = scenario.GetResult(nameof(CoherenceEvaluator));
        Assert.IsTrue(result.Rating >= EvaluationRating.Average,
            $"Coherence rating was {result.Rating}");
    }

    [TestMethod]
    public async Task Chat_responds_relevantly()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_responds_relevantly));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain photosynthesis in one sentence.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenario.EvaluateAsync(messages);

        var result = scenario.GetResult(nameof(RelevanceEvaluator));
        Assert.IsTrue(result.Rating >= EvaluationRating.Average,
            $"Relevance rating was {result.Rating}");
    }
}

